 async function load(){
  setLoading(true);setError('');
  try{
   const [s,a]=await Promise.all([get('/dashboards/me'),list('/activities',{page:1,limit:5})]);
   setSummary(s);setActivities(Array.isArray(a.data)?a.data:[]);setEvents(Array.isArray(s.upcomingEvents)?s.upcomingEvents:[]);
   setInstitution(['DIRECTOR','PRINCIPAL','ADMIN'].includes(user?.role)?await get('/dashboards/institution'):null);
  }catch(e){setError(message(e));}finally{setLoading(false);}
 }
 useEffect(()=>{load();},[user?.role]);
 const counts=summary?.counts||{};
 const cards=institution?[['totalActivities','Total activities',Activity,'blue'],['overdueActivities','Overdue activities',AlertTriangle,'amber'],['users','Active users',Users,'violet'],['departments','Departments',Building2,'teal']]:[['total','Total activities',Activity,'blue'],['inProgress','In progress',Clock3,'violet'],['overdue','Overdue',AlertTriangle,'amber'],['submitted','Awaiting review',FileCheck2,'teal']];
