   <div className="metric-grid">{cards.map(([k,t,I,c])=><div className="metric-card" key={k}><div className={`metric-icon ${c}`}><I size={20}/></div><span>{t}</span><strong>{Number(src[k]||0).toLocaleString()}</strong><small>Current records</small></div>)}</div>
