 async function save(e){e.preventDefault();setBusy(true);setFormError('');try{const payload={title:form.title.trim(),description:form.description,startAt:new Date(form.startAt).toISOString(),endAt:new Date(form.endAt).toISOString(),academicYearId:form.academicYearId,visibility:form.visibility,departmentIds:form.visibility==='DEPARTMENT'&&form.departmentId?[form.departmentId]:[],committeeIds:form.visibility==='COMMITTEE'&&form.committeeId?[form.committeeId]:[],activityId:form.visibility==='ASSIGNED'&&form.activityId?form.activityId:null};await post('/calendar/events',payload);setModal(false);await load();}catch(e){setFormError(message(e));}finally{setBusy(false);}}
